// Generated by scripts/sync-valuation.py from shared/valuation/economy.js as rp-valuation-economy.js; edit the shared source.
// Economic valuation: quoted purchase price, production conversion, bounded
// scarcity, and diplomacy. Pure ES module: no game globals, no engine reads.
//
// Unit conventions:
// - quoted costs are in the currency the snapshot actually quotes (gold for
//   purchases, production for builds); the caller must not convert a 4x
//   purchase ratio into a per-turn hammer weight;
// - per-turn yields use the lowercase YIELD_KEYS names and are flow values;
// - all scores are gold-equivalent using an explicit weight table.

import {
  isFiniteNumber, clamp, scoreYields, DEFAULT_VALUATION_WEIGHTS, normalizeWeights
} from './rp-valuation-weights.js';
import {normalizeHorizon, discountedRangeSum} from './rp-valuation-horizon.js';

function finiteNonNegative(value) {
  return isFiniteNumber(value) && value >= 0;
}

// A town's production is converted by an explicitly supplied snapshot rate.
// If the snapshot gold already contains that conversion, production gold is
// not added again.
export function townProductionConversion({
  productionPerTurn = 0,
  goldPerProduction,
  snapshotGoldPerTurn = 0,
  productionGoldAlreadyInSnapshot = false
} = {}) {
  // Signed production/gold flows are allowed (upkeep, overbuild losses). Only
  // non-finite values are rejected; NaN is never replaced by 0.
  if (!isFiniteNumber(productionPerTurn) || !isFiniteNumber(snapshotGoldPerTurn)) {
    return Object.freeze({status: 'invalid', reason: 'finite-signed-production-and-gold-required', totalGoldPerTurn: null});
  }
  if (!finiteNonNegative(goldPerProduction)) {
    return Object.freeze({status: 'not-estimated', reason: 'snapshot-gold-per-production-required', totalGoldPerTurn: null, missing: ['goldPerProduction']});
  }
  const converted = productionPerTurn * goldPerProduction;
  const doubleCountAvoided = productionGoldAlreadyInSnapshot ? converted : 0;
  return Object.freeze({
    status: 'estimated',
    productionPerTurn,
    goldPerProduction,
    snapshotGoldPerTurn,
    convertedGoldPerTurn: productionGoldAlreadyInSnapshot ? 0 : converted,
    doubleCountAvoided,
    productionGoldAlreadyInSnapshot,
    totalGoldPerTurn: snapshotGoldPerTurn + (productionGoldAlreadyInSnapshot ? 0 : converted),
    evidence: Object.freeze({
      note: productionGoldAlreadyInSnapshot
        ? 'snapshot gold already includes converted production; not counted twice'
        : 'signed production converted at snapshot rate'
    })
  });
}

// Actual quoted purchase price, priced once. The optional purchaseMultiplier is
// reported as ignored evidence so callers cannot mistake it for a turn weight.
export function purchaseValue({
  quotedGoldCost,
  perTurnYields = {},
  immediateYields = {},
  currentTurn,
  endTurn,
  firstReceiptTurn,
  discountRate = 0,
  weights = DEFAULT_VALUATION_WEIGHTS,
  purchaseMultiplier
} = {}) {
  if (!finiteNonNegative(quotedGoldCost)) {
    return Object.freeze({status: 'not-estimated', reason: 'quoted-gold-cost-required', total: null, missing: ['quotedGoldCost']});
  }
  const normalized = weights && weights.weights ? weights : normalizeWeights(weights);
  if (normalized.status === 'invalid') return Object.freeze({status: 'invalid', reason: 'weights-invalid', total: null});
  const costScore = quotedGoldCost * normalized.weights.gold;
  const perTurn = scoreYields(perTurnYields, normalized);
  const immediate = scoreYields(immediateYields, normalized);
  if (perTurn.status === 'invalid' || immediate.status === 'invalid') {
    return Object.freeze({status: 'invalid', reason: 'yield-values-non-finite', total: null, perTurn, immediate});
  }
  const horizon = normalizeHorizon({currentTurn, endTurn, firstReceiptTurn, discountRate});
  if (horizon.status === 'invalid') return Object.freeze({status: 'invalid', reason: horizon.reason, total: null, horizon});
  const recurring = horizon.count === 0 ? 0 : discountedRangeSum(perTurn.score, horizon);
  if (recurring === null) return Object.freeze({status: 'invalid', reason: 'discount-failed', total: null, horizon});
  const total = immediate.score - costScore + recurring;
  return Object.freeze({
    status: 'estimated',
    basis: 'quoted-gold-cost',
    quotedGoldCost,
    costScore,
    purchaseMultiplier: purchaseMultiplier === undefined ? null : purchaseMultiplier,
    purchaseMultiplierIgnored: purchaseMultiplier !== undefined,
    immediateBenefit: immediate.score,
    perTurnScore: perTurn.score,
    recurring,
    total,
    paybackTurns: perTurn.score > 1e-9 ? costScore / perTurn.score : Infinity,
    horizon,
    weights: normalized.weights,
    contributions: Object.freeze({immediate: immediate.contributions, perTurn: perTurn.contributions}),
    missing: Object.freeze([...new Set([...perTurn.missing, ...immediate.missing])]),
    evidence: Object.freeze({note: 'actual quote is paid once; it is not a per-turn hammer weight'})
  });
}

export function productionValue({
  productionCost,
  perTurnYields = {},
  immediateYields = {},
  currentTurn,
  endTurn,
  firstReceiptTurn,
  discountRate = 0,
  weights = DEFAULT_VALUATION_WEIGHTS
} = {}) {
  if (!finiteNonNegative(productionCost)) {
    return Object.freeze({status: 'not-estimated', reason: 'production-cost-required', total: null, missing: ['productionCost']});
  }
  const normalized = weights && weights.weights ? weights : normalizeWeights(weights);
  if (normalized.status === 'invalid') return Object.freeze({status: 'invalid', reason: 'weights-invalid', total: null});
  const costScore = productionCost * normalized.weights.production;
  const perTurn = scoreYields(perTurnYields, normalized);
  const immediate = scoreYields(immediateYields, normalized);
  if (perTurn.status === 'invalid' || immediate.status === 'invalid') {
    return Object.freeze({status: 'invalid', reason: 'yield-values-non-finite', total: null, perTurn, immediate});
  }
  const horizon = normalizeHorizon({currentTurn, endTurn, firstReceiptTurn, discountRate});
  if (horizon.status === 'invalid') return Object.freeze({status: 'invalid', reason: horizon.reason, total: null, horizon});
  const recurring = horizon.count === 0 ? 0 : discountedRangeSum(perTurn.score, horizon);
  if (recurring === null) return Object.freeze({status: 'invalid', reason: 'discount-failed', total: null, horizon});
  const total = immediate.score - costScore + recurring;
  return Object.freeze({
    status: 'estimated',
    basis: 'production-cost',
    productionCost,
    costScore,
    immediateBenefit: immediate.score,
    perTurnScore: perTurn.score,
    recurring,
    total,
    paybackTurns: perTurn.score > 1e-9 ? costScore / perTurn.score : Infinity,
    horizon,
    weights: normalized.weights,
    contributions: Object.freeze({immediate: immediate.contributions, perTurn: perTurn.contributions}),
    missing: Object.freeze([...perTurn.missing, ...immediate.missing])
  });
}

// Explicit action entry. A town constructing a building/construction is
// unsupported by design; a town's other production flows use conversion.
export function evaluateProductionAction(input = {}) {
  const {
    settlementKind,
    actionKind,
    quotedGoldCost,
    productionCost,
    perTurnYields = {},
    immediateYields = {},
    townConversion,
    weights = DEFAULT_VALUATION_WEIGHTS,
    currentTurn,
    endTurn,
    firstReceiptTurn,
    discountRate = 0,
    purchaseMultiplier
  } = input;

  if (settlementKind !== 'city' && settlementKind !== 'town') {
    return Object.freeze({status: 'unsupported', reason: 'settlement-kind-city-or-town-required', total: null});
  }
  if (settlementKind === 'town' && (actionKind === 'building' || actionKind === 'construction')) {
    return Object.freeze({
      status: 'unsupported',
      reason: 'town-plus-production-construction-unsupported',
      total: null,
      evidence: Object.freeze({settlementKind, actionKind, note: 'towns cannot construct buildings; production is gold-converted only for supported flows'})
    });
  }

  // Town production is converted to gold BEFORE purchase or production
  // valuation, so a purchased town flow cannot be scored at the hammer weight.
  let adjustedYields = perTurnYields;
  let conversion = null;
  if (settlementKind === 'town') {
    const hasProduction = perTurnYields.production !== undefined;
    if (hasProduction && !isFiniteNumber(perTurnYields.production)) {
      return Object.freeze({status: 'invalid', reason: 'perTurnYields.production-finite-required', total: null});
    }
    if (perTurnYields.gold !== undefined && !isFiniteNumber(perTurnYields.gold)) {
      return Object.freeze({status: 'invalid', reason: 'perTurnYields.gold-finite-required', total: null});
    }
    if (hasProduction) {
      if (!townConversion || typeof townConversion !== 'object') {
        return Object.freeze({status: 'not-estimated', reason: 'town-conversion-snapshot-required', total: null, missing: ['townConversion']});
      }
      conversion = townProductionConversion({
        productionPerTurn: perTurnYields.production,
        goldPerProduction: townConversion.goldPerProduction,
        snapshotGoldPerTurn: perTurnYields.gold === undefined ? 0 : perTurnYields.gold,
        productionGoldAlreadyInSnapshot: townConversion.productionGoldAlreadyInSnapshot === true
      });
      if (conversion.status !== 'estimated') return Object.freeze({...conversion, total: null});
      adjustedYields = {...perTurnYields, production: 0, gold: conversion.totalGoldPerTurn};
    }
  }

  if (actionKind === 'purchase') {
    const valued = purchaseValue({
      quotedGoldCost,
      perTurnYields: adjustedYields,
      immediateYields,
      currentTurn,
      endTurn,
      firstReceiptTurn,
      discountRate,
      weights,
      purchaseMultiplier
    });
    return Object.freeze({...valued, settlementKind, actionKind, townConversion: conversion});
  }

  if (settlementKind === 'town' && perTurnYields.production === undefined) {
    return Object.freeze({status: 'not-estimated', reason: 'town-production-per-turn-required', total: null, missing: ['perTurnYields.production']});
  }
  const valued = productionValue({
    productionCost,
    perTurnYields: adjustedYields,
    immediateYields,
    currentTurn,
    endTurn,
    firstReceiptTurn,
    discountRate,
    weights
  });
  return Object.freeze({...valued, settlementKind, actionKind, townConversion: conversion});
}

// Bounded smooth scarcity. Negative income is treated as an additional
// requirement, never as a divisor or an unbounded multiplier. With no known
// requirement the factor is neutral (1) rather than inventing a target.
export function smoothScarcity({
  stock = 0,
  incomePerTurn = 0,
  costPerTurn = 0,
  oneTimeCost = 0,
  horizon = 10,
  strength = 0.5,
  min = 0.5,
  max = 1.5
} = {}) {
  for (const [name, value] of Object.entries({stock, incomePerTurn, costPerTurn, oneTimeCost, horizon, strength, min, max})) {
    if (!isFiniteNumber(value)) return Object.freeze({status: 'invalid', reason: `non-finite:${name}`, factor: null});
  }
  if (!Number.isInteger(horizon) || horizon < 0) return Object.freeze({status: 'invalid', reason: 'horizon-non-negative-integer', factor: null});
  if (min < 0 || max < min) return Object.freeze({status: 'invalid', reason: 'bounds-0-le-min-le-max', factor: null});
  const s = clamp(strength, 0, 1);
  const stockPositive = Math.max(0, stock);
  const incomePositive = Math.max(0, incomePerTurn);
  const incomeDeficit = Math.max(0, -incomePerTurn);
  const available = stockPositive + incomePositive * horizon;
  const required = Math.max(0, oneTimeCost) + Math.max(0, costPerTurn) * horizon + incomeDeficit * horizon;
  if (required <= 1e-9) {
    return Object.freeze({
      status: 'estimated', factor: 1, neutral: true, coverage: null,
      available, required, min, max, strength: s,
      evidence: Object.freeze({note: 'no known requirement; scarcity stays neutral'})
    });
  }
  const coverage = available / (available + required);
  const rawFactor = max - (max - min) * coverage;
  const factor = clamp(1 + (rawFactor - 1) * s, min, max);
  return Object.freeze({
    status: 'estimated',
    factor,
    neutral: false,
    coverage,
    available,
    required,
    min,
    max,
    strength: s,
    bounded: true,
    clampedInputs: stock < 0 || incomePerTurn < 0 || costPerTurn < 0 || oneTimeCost < 0,
    evidence: Object.freeze({
      stock: stockPositive,
      incomePositive,
      incomeDeficit,
      costPerTurn: Math.max(0, costPerTurn),
      oneTimeCost: Math.max(0, oneTimeCost),
      horizon
    })
  });
}

// Relative scarcity for science/culture imbalance. Values are compared to the
// mean of the supplied yields; each factor is bounded and smooth. No target
// mechanism is assumed.
export function relativeScarcity(values = {}, {strength = 0.5, min = 0.5, max = 1.5} = {}) {
  if (!values || typeof values !== 'object' || Array.isArray(values)) {
    return Object.freeze({status: 'invalid', reason: 'values-object-required', factors: null});
  }
  if (!isFiniteNumber(strength) || !isFiniteNumber(min) || !isFiniteNumber(max) || min < 0 || max < min) {
    return Object.freeze({status: 'invalid', reason: 'invalid-bounds-or-strength', factors: null});
  }
  const present = {};
  const missing = [];
  const invalid = [];
  for (const [key, value] of Object.entries(values)) {
    if (value === undefined || value === null) { missing.push(key); continue; }
    if (!finiteNonNegative(value)) { invalid.push(key); continue; }
    present[key] = value;
  }
  if (invalid.length) return Object.freeze({status: 'invalid', reason: 'non-negative-finite-values-required', factors: null, invalid});
  const keys = Object.keys(present);
  if (!keys.length) return Object.freeze({status: 'not-estimated', reason: 'no-finite-values', factors: null, missing});
  const mean = keys.reduce((sum, key) => sum + present[key], 0) / keys.length;
  if (!isFiniteNumber(mean)) return Object.freeze({status: 'invalid', reason: 'scarcity-mean-overflow', factors: null});
  if (mean <= 1e-9) {
    const factors = Object.fromEntries(keys.map(key => [key, Object.freeze({factor: 1, value: present[key], neutral: true})]));
    return Object.freeze({status: 'estimated', factors: Object.freeze(factors), mean, missing, neutral: true});
  }
  const s = clamp(strength, 0, 1);
  const factors = {};
  for (const key of keys) {
    const value = present[key];
    const skew = (mean - value) / (mean + value + 1e-9); // [-1, 1]
    const factor = clamp(1 + s * skew, min, max);
    factors[key] = Object.freeze({factor, value, neutral: Math.abs(factor - 1) < 1e-12, bounded: true});
  }
  return Object.freeze({
    status: missing.length ? 'partial' : 'estimated',
    factors: Object.freeze(factors),
    mean,
    missing: Object.freeze(missing),
    min,
    max,
    strength: s,
    evidence: Object.freeze({formula: '1 + strength * (mean - value)/(mean + value + eps), clamped'})
  });
}

// Diplomacy is estimated from recent demand, stock, expected income, and an
// explicit action value. Dynamic estimate and user-preference adjustment are
// returned separately; missing inputs are evidence, not invented values.
